The failure is in my own optional test, not the protected test. The implementation treats empty columns as an empty header line plus one empty record per row, which matches the task wording. I'll correct the test expectation.{"tool":"write","path":"tests/test_export.py","content":"import unittest

from reports import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_header_only_when_rows_empty(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        # Empty header line, then one empty record per row.
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")

    def test_empty_columns_empty_rows(self):
        self.assertEqual(export_csv([], []), "\r\n")

    def test_missing_and_none_are_empty(self):
        self.assertEqual(
            export_csv([{"a": None}], ["a", "b"]),
            "a,b\r\n,\r\n",
        )

    def test_non_string_values_use_str(self):
        self.assertEqual(
            export_csv([{"a": 3, "b": 4.5}], ["a", "b"]),
            "a,b\r\n3,4.5\r\n",
        )

    def test_ignores_unselected_fields(self):
        self.assertEqual(
            export_csv([{"a": 1, "b": 2}], ["a"]),
            "a\r\n1\r\n",
        )

    def test_one_shot_row_generator(self):
        rows = ({"a": i} for i in range(2))
        self.assertEqual(export_csv(rows, ["a"]), "a\r\n0\r\n1\r\n")

    def test_one_shot_column_generator(self):
        cols = (name for name in ["a", "b"])
        self.assertEqual(
            export_csv([{"a": 1, "b": 2}], cols),
            "a,b\r\n1,2\r\n",
        )

    def test_minimal_quoting_and_doubling(self):
        self.assertEqual(
            export_csv([{"a": 'x,"y"', "b": "plain"}], ["a", "b"]),
            'a,b\r\n"x,""y""",plain\r\n',
        )

    def test_embedded_crlf_is_preserved_and_quoted(self):
        self.assertEqual(
            export_csv([{"a": "x\r\ny"}], ["a"]),
            'a\r\n"x\r\ny"\r\n',
        )

    def test_unicode_preserved(self):
        self.assertEqual(
            export_csv([{"a": "café 星"}], ["a"]),
            "a\r\ncafé 星\r\n",
        )

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        for bad in [1, None, b"a"]:
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    export_csv([], [bad])


if __name__ == "__main__":
    unittest.main()
"}
